export interface CheckDef {
    check: string;
}
/** A generic base with a defaulted parameter. */
export interface StringFormatDef<Format extends string = string> extends CheckDef {
    format: Format;
}
/** Extends the base bare, so through its default. */
export interface RegexDef extends StringFormatDef {
    pattern: RegExp;
}
/** Extends the base at a literal argument. */
export interface LowerCaseDef extends StringFormatDef<"lowercase"> {}
export interface StringFormat {
    def: StringFormatDef;
}
export interface StringDef {
    type: "string";
}
/** Applies the base over its own parameter, beside a second base. */
export interface FormatDef<Format extends string = string> extends StringDef, StringFormatDef<Format> {}
export interface Format {
    def: FormatDef;
}

/** A chain to the resolve frontier, ending at the generic base. */
export interface Link0 {
    next: Link1;
}
export interface Link1 {
    next: Link2;
}
export interface Link2 {
    next: Link3;
}
export interface Link3 {
    next: Link4;
}
export interface Link4 {
    next: Link5;
}
export interface Link5 {
    next: Link6;
}
export interface Link6 {
    next: Link7;
}
export interface Link7 {
    next: Link8;
}
export interface Link8 {
    next: Link9;
}
export interface Link9 {
    next: Link10;
}
export interface Link10 {
    next: Link11;
}
export interface Link11 {
    next: Link12;
}
export interface Link12 {
    next: Link13;
}
export interface Link13 {
    next: Link14;
}
export interface Link14 {
    next: Link15;
}
export interface Link15 {
    next: Link16;
}
export interface Link16 {
    next: Link17;
}
export interface Link17 {
    next: Link18;
}
export interface Link18 {
    next: Link19;
}
export interface Link19 {
    next: Link20;
}
export interface Link20 {
    next: StringFormatDef;
}
